<script setup lang="ts">
import {UiButton,UiSelect,UiMetric,UiPanel,UiBadge, UiTabs} from './ui';
import {computed,ref,watch} from 'vue';
import {admissions as a,institutes,fmt,type Institute} from '../data';
import InstituteBadge from './InstituteBadge.vue';
import { instituteStyle } from '../identity';
import Icon from './Icon.vue';import LineChart from './LineChart.vue';import DonutChart from './DonutChart.vue';
const props=withDefaults(defineProps<{initialInstitute?:string}>(),{initialInstitute:'all'});
const emit=defineEmits<{institute:[value:Institute];topic:[id:string];program:[value:{name:string;institute:string;value?:number;metric?:string;level?:string}]}>();
const section=ref(props.initialInstitute==='all'?'overview':'departments');
const trend=ref<'score'|'enrollment'>('score');const level=ref('ВО');const metric=ref('enrolled');const programMetric=ref('applications');const sort=ref('desc');const selected=ref(props.initialInstitute);
watch(()=>props.initialInstitute,id=>{level.value='ВО';selected.value=id;section.value=id==='all'?'overview':'departments';});
const rows=computed(()=>{const r=level.value==='ВО'?institutes.map(i=>({...i})):a.college.institutes.map(i=>({...i,id:i.short}));return r.filter(i=>selected.value==='all'||i.id===selected.value).sort((x,y)=>(sort.value==='desc'?1:-1)*(y[metric.value as 'enrolled'|'students']-x[metric.value as 'enrolled'|'students']));});
const max=computed(()=>Math.max(...rows.value.map(i=>i[metric.value as 'enrolled'|'students']),1));
const programs=computed(()=>level.value==='СПО'?a.college.programs:a.programs.filter(p=>p.metric===programMetric.value));
watch(section,value=>{if(value==='overview'){selected.value='all';sort.value='desc';metric.value='enrolled';}});
const displayRows=computed(()=>section.value==='overview'?rows.value.slice(0,5):rows.value);
function exportData(){const content='\uFEFFПодразделение;Контингент;Зачислено\n'+rows.value.map(i=>`${i.short};${i.students};${i.enrolled}`).join('\n');const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([content],{type:'text/csv;charset=utf-8;'}));link.download='RUT.digital-прием-2026.csv';link.click();URL.revokeObjectURL(link.href);}
function open(id:string){const i=institutes.find(i=>i.id===id);if(i)emit('institute',i);else emit('topic','college-'+id);}
</script>
<template><div class="page-toolbar admissions-toolbar"><UiTabs v-model="section" label="Разделы приёмной комиссии" :items="[{value:'overview',label:'Обзор'},{value:'departments',label:'Подразделения'},{value:'programs',label:'Программы'},{value:'new',label:'Новое в ВО',disabled:level==='СПО'},{value:'geography',label:'Квоты и география'}]"/><div class="toolbar-actions"><UiSelect v-model="level" aria-label="Уровень образования" @change="selected='all';if(section==='new')section='overview'"><option value="ВО">Высшее образование</option><option value="СПО">Колледжи · СПО</option></UiSelect><UiButton class="btn" @click="exportData"><Icon name="download"/> CSV</UiButton></div></div>
<div v-if="section==='overview'" class="kpi-grid"><UiMetric class="kpi"><template #heading><span>Подано заявлений <Icon name="source"/></span></template><template #content><strong>{{fmt(level==='ВО'?a.applications:a.college.applications)}}</strong></template><template #detail><small class="positive">↗ {{level==='ВО'?'+28%':'+2,6%'}} <em>к прошлому году</em></small></template></UiMetric><UiMetric class="kpi"><template #heading><span>Зачислено студентов <Icon name="users"/></span></template><template #content><strong>{{fmt(level==='ВО'?a.enrolled:a.college.enrolled)}}</strong></template><template #detail><small>{{level==='ВО'?'Все формы обучения':'+3,3% к прошлому году'}}</small></template></UiMetric><UiMetric class="kpi"><template #heading><span>{{level==='ВО'?'Средний балл ЕГЭ':'Конкурс на бюджет'}} <Icon name="trend"/></span></template><template #content><strong>{{level==='ВО'?'74,6':'7,2'}} <em>{{level==='ВО'?'балла':'чел./место'}}</em></strong></template><template #detail><small class="positive">{{level==='ВО'?'+5,7 балла · бюджет':'Итоги приёмной кампании'}}</small></template></UiMetric><UiMetric class="kpi"><template #heading><span>Из регионов России <Icon name="map"/></span></template><template #content><strong>{{level==='ВО'?'34':'18'}}<em>%</em></strong></template><template #detail><small>{{fmt(level==='ВО'?a.otherRegions:a.college.otherRegions)}} студентов вне Москвы и МО</small></template></UiMetric></div>
<div v-if="section==='overview'||section==='departments'" class="two-col focus-panels" :class="{'departments-view':section==='departments'}"><UiPanel class="panel"><div class="panel-head"><div><h2>{{section==='overview'?'Лидеры приёма · топ-5':'Приём по подразделениям'}}</h2><p>{{metric==='enrolled'?'Зачислено в 2026 году':'Общий контингент'}} · {{level==='ВО'?'очная форма':'все формы'}}</p></div></div><div v-if="section==='departments'" class="filter-row"><UiSelect v-model="metric" aria-label="Показатель"><option value="enrolled">Зачислено</option><option value="students">Контингент</option></UiSelect><UiSelect v-model="selected" aria-label="Подразделение"><option value="all">Все подразделения</option><option v-for="i in (level==='ВО'?institutes:a.college.institutes.map(i=>({...i,id:i.short})))" :value="i.id" :key="i.id">{{i.short}}</option></UiSelect><UiButton class="icon-btn" title="Изменить сортировку" @click="sort=sort==='desc'?'asc':'desc'"><Icon :name="sort==='desc'?'downArrow':'up'"/></UiButton></div><div class="horizontal-bars admission-bars"><UiButton v-for="i in displayRows" :key="i.id" :style="instituteStyle(i.id)" @click="open(i.id)"><InstituteBadge v-if="level==='ВО'" :id="i.id"/><b v-else>{{i.short}}</b><span class="bar-track"><span :style="{width:`${i[metric as 'students'|'enrolled']/max*100}%`}"></span></span><strong>{{fmt(i[metric as 'students'|'enrolled'])}}</strong><Icon name="arrow" :size="14"/></UiButton></div><UiButton v-if="section==='overview'" class="subtle-link focus-more" @click="section='departments'">Все подразделения <Icon name="right" :size="16"/></UiButton><p v-if="level==='СПО' && section==='departments'" class="footnote">Итог округлён до 1,39 тыс.; сумма подразделений — 1 386.</p></UiPanel>
<div v-if="section==='overview'" class="stack"><UiPanel v-if="level==='ВО'" class="panel"><div class="panel-head"><div><h2>{{trend==='score'?'Качество приёма':'Динамика зачисления'}}</h2><p>{{trend==='score'?'Средний балл ЕГЭ · бюджет':'Все формы обучения'}}</p></div><div class="segmented"><UiButton :class="{active:trend==='score'}" @click="trend='score'">ЕГЭ</UiButton><UiButton :class="{active:trend==='enrollment'}" @click="trend='enrollment'">Приём</UiButton></div></div><div class="chart-headline"><strong>{{fmt(trend==='score'?a.score:a.enrolled)}}</strong><UiBadge class="badge green">{{trend==='score'?'+5,7 балла':'Итог 2026'}}</UiBadge></div><LineChart :key="trend" :values="trend==='score'?a.scoreHistory:a.enrollmentHistory" :labels="a.years"/><UiButton class="subtle-link focus-more" @click="emit('topic','admission-quality')">Качество приёма и сравнение вузов <Icon name="right" :size="16"/></UiButton></UiPanel><UiPanel v-else class="panel"><h2>География приёма в колледжи</h2><UiButton class="subtle-link" @click="emit('topic','college-championship')">Чемпионат транспортных профессий <Icon name="arrow"/></UiButton><DonutChart :items="[{name:'Москва и МО',value:a.college.moscow},{name:'Регионы России',value:a.college.otherRegions}]" label="зачислено"/></UiPanel></div></div>
<div v-if="section==='programs'" class="focus-scroll"><div class="two-col focus-panels programs-view"><UiPanel class="panel"><div class="panel-head"><div><h2>Программы — лидеры приёма</h2><p>{{level==='ВО'?'Пять ведущих программ':'Популярные программы колледжей'}}</p></div><UiSelect v-if="level==='ВО'" v-model="programMetric" aria-label="Рейтинг программ"><option value="applications">По заявлениям</option><option value="competition">По конкурсу</option><option value="score">По баллу ЕГЭ</option></UiSelect></div><div v-for="(p,i) in programs" :key="p.name" class="program-row"><span class="rank">0{{i+1}}</span><div><UiButton class="program-open" @click="emit('program',p)">{{p.name}} <Icon name="arrow" :size="16"/></UiButton><UiButton class="program-institute" @click="open(institutes.find(i=>i.short===p.institute)?.id || p.institute)"><InstituteBadge v-if="level==='ВО'" :id="p.institute"/><span v-else>{{p.institute}}</span></UiButton></div><strong>{{fmt(p.value)}}<small>{{level==='СПО'||programMetric==='applications'?'заявлений':programMetric==='competition'?'чел./место':'балла'}}</small></strong></div></UiPanel></div></div><UiPanel v-if="section==='new'" class="panel focus-scroll"><div class="panel-head"><div><h2>Новые образовательные программы</h2><p>Базовое и специализированное высшее образование</p></div></div><UiButton v-for="p in a.newPrograms" :key="p.name" class="quota-row action-row" @click="emit('program',p)"><span><b>{{p.name}}</b><small class="program-level">{{p.level}}</small></span><InstituteBadge :id="p.institute"/><Icon name="arrow"/></UiButton></UiPanel><div v-if="section==='geography'" class="two-col focus-panels"><UiPanel class="panel"><div class="panel-head"><div><h2>{{level==='ВО'?'Приём по квотам':'Приоритетный приём'}}</h2><p>Итоги 2026 года</p></div></div><div class="quota-row" v-for="q in (level==='ВО'?a.quotas:[{name:'В первоочередном порядке',value:89,change:14.1}])" :key="q.name"><span>{{q.name}}</span><strong>{{q.value}}</strong><UiBadge v-if="q.change" class="badge" :class="q.change>0?'green':'orange'">{{q.change>0?'+':''}}{{q.change}}%</UiBadge></div><div v-if="level==='ВО'" class="insight"><Icon name="trend"/>74,6 — выше среднего по стране: 70,1 <span>(данные по стране за 2025 г.)</span></div></UiPanel><UiPanel v-if="level==='ВО'" class="panel"><div class="panel-head"><div><h2>География поступления</h2><p>Топ регионов за исключением Москвы и МО</p></div></div><div v-for="r in a.regions" :key="r.name" class="quota-row"><span>{{r.name}}</span><b>{{r.value}}</b></div><div class="insight"><Icon name="users"/>5 победителей и призёров олимпиад зачислены в 2026 году</div><UiButton variant="secondary" @click="emit('topic','admission-quality')">Качество и детали квот <Icon name="right"/></UiButton></UiPanel><UiPanel v-if="level==='СПО'" class="panel"><h2>География приёма в колледжи</h2><UiButton class="subtle-link" @click="emit('topic','college-championship')">Чемпионат транспортных профессий <Icon name="arrow"/></UiButton><DonutChart :items="[{name:'Москва и МО',value:a.college.moscow},{name:'Регионы России',value:a.college.otherRegions}]" label="зачислено"/></UiPanel></div></template>
